INSERT INTO "cards" ("id", "lesson_id", "title", "sort_order", "instruction", "created_at", "updated_at") VALUES
	(101010101, 1010101, '흥분을 가라앉히는 평생 신호', 1, '앉아는 산책·기압(놀람) 등 흥분할 만한 상황에서 흥분을 가라앉힐 때 주로 쓰는, 앞으로 가장 자주 쓰게 될 신호예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101010102, 1010101, '조용한 방, 작은 간식, 단어 통일', 2, '주변 자극이 적은 조용한 방에서 작은 간식을 준비해 주세요. 가족 모두가 “앉아”라는 같은 단어를 사용하면 강아지가 덜 헷갈려요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101010103, 1010101, '코앞 → 머리 위 → 머리 뒤로 천천히', 3, '간식을 강아지 코앞에 가져가 주세요. 그대로 머리 위쪽으로 천천히 들어 올리고, 다시 머리 뒤쪽으로 이동시켜 주세요. 고개를 따라 들다가 결국 주저앉아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101010104, 1010101, '앉는 순간이 보상 타이밍', 4, '엉덩이가 바닥에 닿는 그 순간 간식을 주세요. 이미 그냥 앉아 있으면 그 순간을 그대로 보상해도 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101010105, 1010101, '보상 전에 만지지 않기', 5, '아무리 잘했어도 먹이를 주기 전에 만지는 것으로 보상하지 마세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101010106, 1010101, '영상에 나온 반응만', 6, '강아지가 점프하면 엉덩이를 살짝 밀어 앉도록 도와주세요. 엉덩이를 세게 누르거나 큰 소리로 강요하면 앉기를 싫어할 수 있으니 피해주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101010107, 1010101, '루어를 따라 매번 앉으면 다음으로', 7, '간식을 머리 위로 올릴 때마다 자연스럽게 앉는다면 다음 레슨인 ‘말 붙이기’로 넘어가세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101010201, 1010102, '동작에 말을 입힌다', 1, '이미 나오는 동작에 단어를 입히는 단계예요. 명령으로 동작을 만드는 게 아니에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101010202, 1010102, '앉는 타이밍에 "앉아"', 2, '엉덩이가 내려가는 바로 그 타이밍에 "앉아"라고 말하고 보상해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101010203, 1010102, '빈손 → 말만으로', 3, '간식 없이 빈손으로만 해보고, 익숙해지면 "앉아" 구어만으로 앉게 해 주세요. 간식을 얻을 수 있다는 기대감으로 앉게 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101010204, 1010102, '2개월이면 말은 아직이다', 4, '생후 2개월이면 명령어를 알아듣지 못해요. 먹이를 코 위로 들어 앉으면 그냥 주는 식으로 ''형태''만 경험시키고, 3개월부터 말을 붙여 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101010205, 1010102, '말만으로 앉으면 다음 과정으로', 5, '간식으로 유도하지 않아도 “앉아”라는 말에 앉을 수 있다면 다음 과정으로 넘어가세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020101, 1010201, '앉아의 완성은 눈맞춤이다', 1, '앉아·기다려는 그냥 앉히는 게 아니에요. 앉아서 보호자와 눈이 마주쳐야 흥분이 진정되는, 모든 훈련의 기초로, 숫자를 먼저 배우는 것과 같아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020102, 1010201, '간식 들고 정지하지 말 것', 2, '간식을 든 채 숨도 안 쉬고 강아지 코앞에 붙어 있지 마세요. 그건 훈련이 아니라 먹을 것에 대한 흥분만 키워요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020103, 1010201, '움직이며 앉히고, 손을 뻗어 기다리기', 3, '보호자가 움직이면서 강아지를 앉혀 주세요. 앉으면 간식 든 손을 옆으로 쭉 뻗고 가만히 두세요. 강아지가 손이 아니라 보호자 눈을 쳐다보는 순간 간식을 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020104, 1010201, '떨어지는 연습', 4, '눈맞춤이 되면 보호자가 강아지에게서 떨어졌다가 돌아오는 연습을 해 주세요. 조금 떨어져도 다시 돌아온다는 믿음을 주는 연습이며, 나중에 초인종·손님 상황과 분리불안 교육의 바탕이 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020105, 1010201, '윽박지르면 주눅 든다', 5, '"앉아! 기다려!" 식으로 몰아붙이지 마세요. 주눅 들게 만드는 것은 진정이 아니에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020106, 1010201, '이 기초가 돼야 짖음 교정이 먹힌다', 6, '앉은 상태에서 보호자와 눈을 맞추고, 보호자가 잠시 떨어져도 기다릴 수 있으면 짖음과 흥분을 다루는 교육도 훨씬 수월해져요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020201, 1010202, '간식은 양손을 번갈아', 1, '간식을 한 손으로만 주지 말고 양손을 번갈아 주세요. 오른손으로만 훈련하면 왼손으로는 못 하는 개가 많아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020202, 1010202, '단·방석 위에서, 정확히 앉을 때 보상', 2, '약간 단이 높은 곳이나 방석 위에서 해 주세요. 앉아와 엎드려를 한 번에 해버리는 개라면, 정확히 ''앉는'' 순간에 보상해 행동을 구분해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020203, 1010202, '한 손은 간식, 한 손은 몸 만지기', 3, '한 손으로 간식을 주면서 다른 손으로 몸을 만져 주세요. 몸 터치에 대한 스트레스를 낮추는 로우스트레스 핸들링이 함께 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020204, 1010202, '짖으면 주지 않기', 4, '답답해서 짖는 개가 있어요. 짖을 때 놀라서 간식을 주면 짖는 것을 가르치는 거예요. 짖음엔 주지 말고, 원하는 행동(예: 엎드림)이 나올 때 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020205, 1010202, '양손 어느 쪽이든, 만져도 앉아 유지', 5, '왼손과 오른손 어느 쪽으로 유도해도 앉고, 몸을 만지는 동안 자세를 유지하면 잘하고 있는 거예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020301, 1010203, '산만한 곳으로 확장', 1, '집에서 충분히 되면 공원, 사람 많은 곳 등 더 산만한 상황에서 같은 방법으로 연습해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020302, 1010203, '흥분 상황에서 실전 사용', 2, '산책처럼 흥분하기 쉬운 상황에서도 “앉아”를 사용해 보세요. 보호자에게 집중하며 차분해지는 것이 이 신호의 목적이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020303, 1010203, '칭찬과 보상으로만', 3, '낯선 장소에서도 강압하지 말고 칭찬과 간식으로 연습해 주세요. 편안한 경험이 쌓여야 어디서든 안정적으로 앉을 수 있어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(101020304, 1010203, '낯선 환경에서도 앉으면 완료', 4, '낯선 환경에서도 말만 듣고 앉을 수 있으면 ‘앉아’ 교육을 마친 거예요. 이후에는 ‘엎드려’를 이어서 연습해 보세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102010101, 1020101, '기다려는 ''먹이를 바로 안 주는 것''에서 시작하기', 1, '앉아가 되는 강아지에게, 앉았다고 먹이를 바로 주지 말고 잠깐 들고 있어 주세요. 이 참는 순간이 기다려의 시작이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102010102, 1020101, '먹이(사료·한입 간식)와 앉아', 2, '앉아(ST)가 먼저 되어야 해요. 먹이는 손에 쥐어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102010103, 1020101, '보상 타이밍은 보호자가 정하기', 3, '강아지가 스스로 일어나기 전에, 보호자가 정한 순간에 먹이를 주세요. 자기가 일어나게 두지 마세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102010104, 1020101, '던져줄 때까지 끝까지 기다리게 하기', 4, '앉아·엎드려 상태에서 시간을 조금씩 늘리고, 먹이를 던져줄 때까지 스스로 움직이지 않게 해 주세요. 한 번 끝나면 가볍게 터치해 초기화하고 다시 기다리게 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102010105, 1020101, '영상에 나온 반응만', 5, '기다리는 동안 잠시 숨이 가빠질 수 있어요. 강아지가 힘들어하면 시간을 줄이고, 억지로 버티게 하지 말고 짧게 성공하는 경험부터 만들어 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102010106, 1020101, '다음 훈련', 6, '보호자가 간식을 줄 때까지 앉은 자세를 유지하면 잘하고 있는 거예요. 다음 단계에서는 이 행동에 ‘기다려’라는 말을 붙여 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102010201, 1020102, '해제어 전까지 움직이지 않기', 1, '이 훈련의 목표는 ''기다려''에 인내심을 갖고, 풀어주는 말을 듣기 전까지 움직이지 않는 거예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102010202, 1020102, '앉히고 ''기다려'' 2초', 2, '강아지를 앉히고 "기다려"라고 말한 뒤 2초 동안 가만히 바라봐 주세요. 2초를 가만히 앉아 있으면 칭찬하고 작은 간식(또는 사료 한두 알)을 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102010203, 1020102, '한 걸음씩 물러났다 돌아와 보상', 3, '숙달되면 "기다려" 후 한 걸음 뒤로 물러났다가 다시 다가가 칭찬·보상해 주세요. 두세 걸음까지 늘리고, 시간과 거리를 점차 늘려 반복해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102010204, 1020102, '해제어로 끝을 알려주기', 4, '충분히 숙달되면 "쉬어" 같은 해제 단어를 정해 말하고, 더 이상 기다리지 않아도 된다는 것을 알려 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102010205, 1020102, '하루 2번, 5분 이내', 5, '하루 2번 정도, 1회 5분 이내로 해 주세요. 길어도 10분은 절대 넘기지 마라 — 집중하지 못해 훈련 효과가 떨어져요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102010206, 1020102, '2초를 못 참는 경우의 처방은 이 영상에 없다', 6, '2초도 기다리기 어렵다면 시간을 더 짧게 줄여 성공부터 만들어 주세요. 해제 신호 전까지 편안하게 기다릴 수 있으면 다음 단계로 넘어가세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102020101, 1020201, '''이 곳을 찜하고 있는다''는 생각', 1, '기다려는 명령으로 억누르는 게 아니라, 방석 위에서 잠깐 대기하는 것을 가르치는 거예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102020102, 1020201, '방석과 간식', 2, '편안하게 머물 수 있는 방석과 좋아하는 간식을 준비해 주세요. 특별한 장비보다 강아지가 좋아하는 보상을 사용하는 것이 중요해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102020103, 1020201, '방석 위에서 두 가지 보상', 3, '방석 위에 간식을 미리 놓아 우연히 찾아 먹게 하고, 강아지가 방석에 올라올 때 손으로도 직접 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102020104, 1020201, '부르지 않기', 4, '''이리 와''로 부르지 마세요. 특히 어린 강아지는 부를수록 통제받는다고 느껴요. 다른 곳을 왔다 갔다 할 때는 보상하지 않는다 — 노란 방석 위에서만 간식이 나오게 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102020105, 1020201, '올라가 머무는 순간 보상', 5, '강아지를 부르지 말고 스스로 방석에 올라가기를 기다려 주세요. 방석 위에 머무는 순간 바로 칭찬하고 보상해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102020106, 1020201, '스스로 올라오면 심화로', 6, '부르지 않아도 스스로 방석에 올라가 잠깐 머물 수 있으면 심화 단계로 넘어가세요. 어린 강아지는 집중 시간이 짧으니 짧게 끝내도 괜찮아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102020201, 1020202, '기다려 = 동작을 멈추고 그 자리에 대기', 1, '‘기다려’는 동작을 멈추고 그 자리에서 잠깐 대기하는 신호예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102020202, 1020202, '간식을 하나씩 줘 방석에 올라가게 하기', 2, '방석 위에서 간식을 하나씩 주며 머무는 시간을 늘려 주세요. 보호자가 일어서거나 한 걸음 물러나도 방석에 있으면 다시 보상해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102020203, 1020202, '다른 데로 가도 부르지 않기', 3, '보호자가 다른 데로 이동할 때 강아지에게 오라고 하지 마세요. 쪼그려 앉으면 오라는 신호가 되니 주의해 주세요. 강아지가 따라왔더라도 간식을 주지 말고, 자극적으로 칭찬하지도 마세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102020204, 1020202, '방석 쪽으로 걸어가 보상하기', 4, '강아지가 방석에 머물러 있으면 보호자가 다시 방석 쪽으로 다가가 보상해 주세요. 강아지를 불러 움직이게 하지 않는 것이 중요해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102020205, 1020202, '거리를 늘리고 손바닥을 보여주며 다가간다', 5, '숙련되면 거리를 더 벌려 주세요. 다가갈 때는 무릎 방향을 강아지 쪽으로 하고 손바닥을 계속 보여주면서 가까이 가 보상해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102020206, 1020202, '잠깐 대기가 되면 충분하다', 6, '보호자가 조금 떨어져도 방석에서 잠깐 기다릴 수 있으면 충분히 잘한 거예요. 짧은 대기부터 일관되게 반복해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102030101, 1020301, '기다려에는 시간·거리·강도 세 요소가 있다', 1, '간식 앞에서만 참는 기다려는 일부분이에요. 시간과 거리를 따로따로 늘려야 진짜 ‘기다려’예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102030102, 1020301, '''기다려''는 딱 한 번만', 2, '"기다려"라고 한 번만 명확하게 말해 주세요. 반복하지 마세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102030103, 1020301, '가는 척했다가 바로 돌아와 ''옳지''', 3, '한 발짝을 다 가지 말고, 가는 척만 했다가 바로 돌아서서 "옳지" 하고 보상해 주세요. 이것을 5~10번 반복해 주세요. 보상할 때 허리를 숙이지 말고 무릎을 숙여라 — 점프를 막아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102030104, 1020301, '2초부터, 과제식으로 시간만 늘린다', 4, '거리는 가까이 둔 채, 뒷걸음치지 않고 2초 앉아 있기부터 시작해 주세요. 되면 5초로. "옳지" 이후에는 한 박자 쉬고 손을 움직여 간식을 줘라 — 옳지와 동시에 손이 나가면 안 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102030105, 1020301, '실패하면 난이도를 낮춘다 (영상 명시)', 5, '움직였으면 강아지가 바보인 게 아니라 난이도를 많이 올린 거예요. 성공했던 짧은 시간으로 되돌려 주세요. 실패 자체는 나쁘지 않다 — 실패해 봐야 언제 칭찬받는지 이해해요. 싫어하면 거기서 끝내 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102030106, 1020301, '시간이 견뎌지면 거리로', 6, '2~5초 동안 편안하게 기다릴 수 있으면 거리 연습으로 넘어가세요. 시간과 거리를 한꺼번에 늘리지 말고 한 가지씩 조절해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102030201, 1020302, '한 발자국부터 세 발자국까지', 1, '"기다려" 후 한 발자국 갔다가 돌아와 "옳지". 되면 두 발자국, 세 발자국으로 거리만 늘려 주세요. 세 발자국에서는 5초를 속으로 세고 돌아와 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102030202, 1020302, '움직이면 직전 수준으로', 2, '세 발자국+5초에서 3초 만에 움직였으면 시간을 많이 올린 거예요. 두 발자국부터 다시 가거나 세 발자국+3초로 낮춰 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102030203, 1020302, '변형 과제: 등 돌리기·한 바퀴·벽 터치', 3, '정면을 보며 좌우로 가기, 벽을 터치하고 오기, 강아지를 한 바퀴 돌고 오기 같은 변형을 조금씩 쪼개서 성공시켜 주세요. 등을 완전히 보이면 실패하기 쉬우니 처음엔 정면을 보면서 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102030204, 1020302, '시야에서 잠깐 사라졌다 바로 복귀', 4, '문을 열고 아주 잠깐 사라졌다가 바로 돌아와 "옳지". 사라져 있는 시간을 조금씩 늘려 주세요. 실수해도 ''옳지''를 이미 말했다면 칭찬해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102030205, 1020302, '놀이처럼, 온 가족이, 여러 공간에서', 5, '하루 5분씩 2번, 훈련이 아니라 놀이로 해 주세요. 가족 모두가 돌아가면서 해야 효과가 가장 좋아요. 거실에서만 하지 말고 안방·작은 방, 그다음 조용한 야외로 옮겨 주세요. 강아지가 자리를 뜨고 냄새를 맡으면 쉬는 시간 신호다 — 쉬게 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102030206, 1020302, '과제 1~15, 3개월 마스터 목표', 6, '릴렉세이션 프로토콜의 과제를 약 3개월 동안 천천히 익혀 보세요. 서두르지 않고 반복하면 일상에서 흥분을 조절하는 데 도움이 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102040101, 1020401, '보상은 간식이 아니라 ''나가는 것''', 1, '문이 열리면 튀어나가는 것은 위험해요. 이 훈련의 보상은 간식이 아니라 밖으로 나가는 것 자체예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102040102, 1020401, '문 대각선에 선다', 2, '목줄을 채우고, 문이 열리는 쪽 대각선에 서 주세요. 강아지가 나가려 할 때 몸으로 막기(블로킹) 위한 위치예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102040103, 1020401, '문을 살짝 열고, 움직이면 바로 닫는다', 3, '앉아·기다려를 시키고 문을 살짝씩 열어 주세요. 강아지가 움직이면 문을 즉시 닫고 다시 앉아·기다려부터. 줄에 텐션을 살짝 줘도 돼요. 처음에는 인내심이 필요해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102040104, 1020401, '다 열려도 기다리면 "옳지, 가자"', 4, '문이 다 열려도 기다리고 있으면 그때 "옳지"라고 말하고 함께 나가 주세요. 나가는 것이 보상이 되는 순간이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102040105, 1020401, '방문 → 현관 → 엘리베이터 → 아파트 현관', 5, '집 안 안방·방문에서 먼저 연습하고, 그다음 현관문, 그다음 엘리베이터, 가능하다면 아파트 공동현관까지 같은 방식으로 확장해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102040106, 1020401, '흥분도가 떨어진다', 6, '문이 열려도 보호자 허락이 있어야 나갈 수 있다는 인식이 생기면 흥분도가 떨어져 밖에서도 차분하게 산책할 수 있어요. 갑자기 문·엘리베이터에서 튀어나가 다른 사람이 놀라는 일(펫티켓)도 막아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102040201, 1020402, '문 열고 기다려는 50%짜리다', 1, '문을 열어 놓고 기다려만 시키고 그냥 나가는 것은 절반짜리 훈련이에요. 문 안에서 50%, 나와서 50%가 채워져야 100%예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102040202, 1020402, '문 열고 ''기다려'' → ''나와''', 2, '문을 열고 "기다려"를 시켜 주세요. 튀어나가려는 충동을 참게 한 뒤 "나와"라고 말해 문을 넘어오게 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102040203, 1020402, '나오자마자 다시 ''기다려'' → ''가자''', 3, '문을 넘어오면 바로 다시 "기다려"를 시켜 주세요. 안과 밖의 흥분 차이를 한 번 끊어준 다음 "가자"로 출발해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102040204, 1020402, '안팎 모두 기다리면 완료', 4, '문 안과 밖에서 모두 기다릴 수 있으면 이번 단계를 마친 거예요. 다음에는 공원처럼 자극이 있는 곳에서 거리를 두고 기다리는 연습을 해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050101, 1020501, '산책이 안 풀리면 공원 기다려부터', 1, '산책 훈련을 따라 해도 안 되는 개는 산책보다 먼저, 사람들이 지나다니는 공원에서 떨어져 기다리는 힘을 만들어야 해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050102, 1020501, '바닥 선이 있는 놀이터 근처', 2, '목줄·간식을 챙기고, 바닥 타일 선이 있는 공간을 골라 주세요. 놀이터 근처가 좋다 — 아이들의 빠른 움직임이 적당한 자극이 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050103, 1020501, '한 칸씩 거리 벌리기', 3, '타일 선을 경계로 "기다려"를 시키고 보호자가 한 발(한 칸) 나가 주세요. 선을 넘지 않으면 "옳지"와 보상, 그다음 두 칸으로 넓혀 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050104, 1020501, '넘어오면 처음 자리로 정확히 되돌린다', 4, '선을 넘어 따라 나오면 "안돼" 하고 처음 기다리던 자리로 정확히 되돌려 주세요. 선생님 쪽으로 가까워진 자리가 아니라 원래 그 자리예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050105, 1020501, '손은 뒤로, 몸은 앞으로', 5, '자꾸 따라 나오면 신호 손은 뒤쪽으로 뻗은 채 몸만 앞으로 나가 주세요. 손으로 "기다려" 신호를 확실히 주면서 몸이 먼저 거리를 벌리는 방식이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050106, 1020501, '선을 안 넘으면 다음으로', 6, '한두 칸 떨어진 거리에서도 기준선을 넘지 않고 기다릴 수 있으면 다음 단계로 넘어가세요. 보호자 뒤에서 안정적으로 기다리는 경험을 만들어 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050201, 1020502, '신호 손은 한 자리에 고정', 1, '"기다려" 신호를 준 손은 그 위치에 고정해 주세요. 강아지가 방향을 돌아도 손이 따라다니면 안 된다 — 내 몸만 움직여요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050202, 1020502, '쳐다보면 칭찬·간식', 2, '기다리던 강아지가 보호자를 쳐다보면 그 순간 "옳지"와 칭찬·간식을 주세요. 계속 주시하게 만드는 보상이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050203, 1020502, '가벼운 터치 = 초기화', 3, '자극에 두리번거리면 몸을 가볍게 터치해 주세요. 자극을 빨리 잊고 초기화하는 신호예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050204, 1020502, '보상하러 갈 때 움직이면 보상 무효', 4, '보호자가 보상을 주러 다가가는데 강아지가 움직이면 그 보상은 성립하지 않아요. "기다려"를 다시 시키고, 가만히 기다린 상태에서 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050205, 1020502, '주시하며 자리 유지', 5, '거리를 둔 상태에서도 보호자를 바라보며 자리를 지킬 수 있으면 다음 단계로 넘어가세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050301, 1020503, '사람이 지나간 뒤에 간식', 1, '사람이 지나가는 동안 기다리게 하고, 완전히 지나간 뒤 간식을 주세요. 보상 후에는 다시 기다리는 자세로 돌아가 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050302, 1020503, '거리를 더 벌리고 유혹을 늘린다', 2, '보호자와의 거리를 조금 더 벌리고 주변 움직임도 하나씩 추가해 주세요. 강아지가 기준선을 넘기 전에 미리 신호를 주는 타이밍을 익혀 보세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050303, 1020503, '마무리에 간식을 쏟아붓지 않기', 3, '훈련을 마무리하며 간식을 많이 주면서 끝내지 마세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(102050304, 1020503, '자극→진정 패턴이 완성 기준', 4, '간헐적으로 오는 자극 속에서 ''자극 → 진정''이 반복되며 유지되면 완성이에요. 이 훈련 자체가 보호자와 반려견 사이 신뢰의 척도예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103010101, 1030101, '강아지는 냄새와 발바닥 감각으로 화장실을 구분하기', 1, '강아지는 냄새와 발바닥 감각으로 화장실을 구분해요. 소변 냄새가 있는 곳, 푹신한 촉감이 학습된 곳이 화장실이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103010102, 1030101, '개에게 집 안은 사방이 화장실 후보다', 2, '개에게 집 안은 사방이 화장실 후보다 — 지정된 한 곳에만 싸는 것은 어려운 일이고, 잘하고 있다면 칭찬받아 마땅해요. 실수의 원인은 대부분 불완전한 교육이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103010103, 1030101, '자는 곳·먹는 곳에서 최대한 멀리 싸는 것이 본능이다', 3, '먼저 이 내용을 기억해 주세요. 자는 곳·먹는 곳에서 최대한 멀리 싸는 것이 본능이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103010104, 1030101, '배변 훈련에 ''완벽히 배웠다''는 없다(70~80% 이해)', 4, '배변 교육은 한 번에 완벽해지지 않아요. 실수했을 때 혼내면 불안이 커질 수 있으니 조용히 정리하고 다음 성공 기회를 만들어 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103010201, 1030102, '화장실은 최대한 먼 반대쪽에 정하기', 1, '잠자리(켄넬·방석)와 밥·물그릇을 한쪽에, 화장실은 최대한 먼 반대쪽에 정해요. 좁으면 몇 걸음이라도 떨어뜨려요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103010202, 1030102, '처음엔 패드 한 장만 멀리 두지 말고 생활 구역 안에 넓게 깐다', 2, '처음에는 생활 구역 안에 패드를 넓게 깔아 주세요. 몸을 돌며 배변하는 강아지는 큰 패드를 사용하고, 미끄러지지 않도록 바닥에 고정해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103010203, 1030102, '간식: 한입에 먹을 수 있고 잘 잘라지는 것', 3, '간식: 한입에 먹을 수 있고 잘 잘라지는 것. 사료도 훌륭해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103010204, 1030102, '무향 효소 탈취제 준비 — 향으로 덮지 말고 소변 냄새 성분을 분해하기', 4, '무향 효소 탈취제 준비 — 향으로 덮지 말고 소변 냄새 성분을 분해해요. 냄새가 남으면 같은 자리에 또 싸요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103020101, 1030201, '화장실은 패드를 가르치는 게 아니라 좋아하는 장소를 가르치는 게 먼저다', 1, '어린 강아지에게는 패드보다 편안한 장소를 먼저 알려주는 것이 좋아요. 방석과 한입 크기의 간식을 준비해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103020102, 1030201, '''여기는 자고 먹고 쉬는 곳''', 2, '방석 옆에서 간식을 손으로 주고, 방석 틈에도 숨겨 스스로 찾아 먹게 해주세요. 방석을 자고 먹고 쉬는 편안한 장소로 느끼게 하는 과정이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103020103, 1030201, '방석(좋아하는 장소) 주변으로 패드를 둥그렇게 깐다', 3, '방석(좋아하는 장소) 주변으로 패드를 둥그렇게 깔아요. 위치는 보호자가 원하는 곳이어도 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103020104, 1030201, '패드 쪽으로 오면 간식을 그냥 하나씩 주기', 4, '패드 쪽으로 오면 간식을 그냥 하나씩 준다 — 목표는 ''여기 가면 간식 있겠지'' 수준까지만. 패드 위에서 맛있게 먹고 재밌게 놀아 주고 반복해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103020105, 1030201, '다른 데 싸도 놀라지 않는다 — 반응 없이 조용히 치우고 다시 반복하기', 5, '이 순서대로 천천히 연습해 주세요. 다른 데 싸도 놀라지 않는다 — 반응 없이 조용히 치우고 다시 반복해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103020106, 1030201, '반복하다 보면 패드에 싸는 순간들이 온다', 6, '반복하다 보면 강아지가 패드에 배변하는 순간이 찾아와요. 강아지마다 속도가 다르니 며칠 동안 여유 있게 관찰해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103020201, 1030202, '패드 배변 성공이 시작되면 그것이 전환 신호다', 1, '이번 단계에서 배울 내용을 알려드릴게요. 패드 배변 성공이 시작되면 그것이 전환 신호예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103020202, 1030202, '패드 위에 간식 두는 것을 멈춘다', 2, '이 순서대로 천천히 연습해 주세요. 패드 위에 간식 두는 것을 멈춰요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103020203, 1030202, '대신 패드에 올라가면 얼굴에(손으로 직접) 먹이를 주기', 3, '이 순서대로 천천히 연습해 주세요. 대신 패드에 올라가면 얼굴에(손으로 직접) 먹이를 줘요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103020204, 1030202, '규칙이 바뀌면 의심·항의·긴장할 수 있고, 긴장하면 배설할 수도 있다', 4, '이 부분은 꼭 주의해 주세요. 규칙이 바뀌면 의심·항의·긴장할 수 있고, 긴장하면 배설할 수도 있다 — 놀라지 말고 새 규칙을 차분히 유지해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103020205, 1030202, '패드를 치울 일이 있으면(밥 줄 때 등) 간식을 주는 동안 천천히 치운다', 5, '이 순서대로 천천히 연습해 주세요. 패드를 치울 일이 있으면(밥 줄 때 등) 간식을 주는 동안 천천히 치워요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103020206, 1030202, '''패드 배변 → 얼굴 보상'' 루프가 자리잡으면 훈련 3으로', 6, '패드에 배변한 뒤 보호자를 바라보는 흐름이 자연스러워지면 다음 단계로 넘어가세요. 패드 위 간식은 처음 유도할 때만 짧게 사용하고, 성공하기 시작하면 패드 밖에서 보상해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103030101, 1030301, '배변 확률이 높은 순간을 외운다', 1, '기상 직후, 식사나 물을 마신 뒤, 놀이가 끝난 뒤처럼 배변 가능성이 높은 순간을 기억해 주세요. 바닥 냄새를 맡으며 빙빙 돌 때도 바로 화장실로 안내해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103030102, 1030301, '타이밍이 오면 강아지보다 먼저 움직여 패드 근처로 데려간다', 2, '타이밍이 오면 강아지보다 먼저 움직여 패드 근처로 데려가요. 패드에 올려두고 말 걸기보다 옆에서 조용히 기다려요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103030103, 1030301, '패드에 올라간 것만으로 소리 내거나 간식을 주지 않기', 3, '패드에 올라간 것만으로 소리 내거나 간식을 주지 않아요. 배변이 시작되면 끝까지 기다린다 — 빨리 반응하면 배변을 멈추거나 ''올라갔다 내려오기''만 반복하는 개가 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103030104, 1030301, '배변이 끝나는 순간 짧은 칭찬어', 4, '배변이 끝나는 순간 짧은 칭찬어. 간식은 패드 밖으로 한두 걸음 나오게 한 뒤 준다 — ''패드 배변=좋은 일''이지 패드가 ''먹는 자리''가 아니에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103030105, 1030301, '끝난 직후 칭찬 → 패드 밖 간식이 습관이 되면 성공', 5, '배변이 끝난 직후 짧게 칭찬하고 패드 밖에서 간식을 주세요. 이 흐름이 자연스럽게 이어지면 잘하고 있는 거예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103030201, 1030302, '소리 지르거나 코를 실수 자리에 대게 하지 않기', 1, '소리 지르거나 코를 실수 자리에 대게 하지 않는다 — 시간이 지나면 개는 이유를 연결하지 못해요. 무향 효소 탈취제로 닦아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103030202, 1030302, '같은 자리 반복 실수는 그 물건을 치우거나 접근을 막는다', 2, '같은 자리 반복 실수는 그 물건을 치우거나 접근을 막아요. 푹신한 물건(이불·러그·발매트) 실수는 촉감·냄새가 배변 장소로 남은 것 — 치우고 냄새를 지우고 주변에 패드를 넓게 다시 깔아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103030203, 1030302, '자리를 잡으면: 며칠 기록해 자주 쓰는 패드 위치를 파악', 3, '며칠 동안 기록해 자주 사용하는 패드 위치를 확인해 주세요. 덜 사용하는 패드부터 천천히 줄이고, 위치도 한 번에 멀리 옮기지 마세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103030204, 1030302, '줄이자 실패가 늘면 기준을 너무 빨리 바꾼 것', 4, '아래 상태가 되면 이번 단계를 잘 마친 거예요. 줄이자 실패가 늘면 기준을 너무 빨리 바꾼 것 — 마지막 성공했던 패드 수·위치로 돌아가 며칠 더 유지해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103040101, 1030401, '대상: 실내에서만 생활하는 강아지', 1, '대상: 실내에서만 생활하는 강아지. 크레이트 크기: 엎드려 쉬기엔 충분하지만 한쪽에 용변은 볼 수 없을 만큼 약간 좁게. 크레이트는 감금 도구가 아니라 개의 ''자기 방이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103040102, 1030401, '아침에 깨면 즉시 크레이트 밖으로 꺼내 정해진 화장실로 데려간다', 2, '아침에 깨면 즉시 크레이트 밖으로 꺼내 정해진 화장실로 데려가요. 용변을 보는 순간 ''쉬'' 같은 짤막한 신호음을 내고, 마치면 작은 간식·사료 한 알을 줘요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103040103, 1030401, '안 싸고 돌아다니기만 하면 다시 크레이트에 넣고 15분 후 다시 꺼낸다', 3, '화장실에 데려갔는데 배변하지 않으면 다시 크레이트에서 15분 정도 쉬게 해주세요. 배변할 때까지 같은 간격으로 차분히 반복해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103040104, 1030401, '낮에는 계속 관찰하기', 4, '낮에는 계속 관찰해요. 냄새 맡으며 돌아다니는 배변 신호가 보이면 즉시 화장실로 — 같은 루틴. 깨어 있는 16시간 동안 6~8회 반복해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103040105, 1030401, '''쉬'' 소리가 조건반사로 각인되면 성공', 5, '배변할 때 들려주는 “쉬”라는 말에 자연스럽게 반응하기 시작하면 잘하고 있는 거예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103040201, 1030402, '잠자기 30분 전부터 물그릇·밥그릇을 치운다', 1, '잠자기 30분 전부터 물그릇·밥그릇을 치워요. 마지막으로 대소변을 보게 한 뒤 크레이트에서 문을 닫고 재워요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103040202, 1030402, '3개월 이하 퍼피는 방광 조절력이 약해 하룻밤을 참기 힘들 수 있다', 2, '이 부분은 꼭 주의해 주세요. 3개월 이하 퍼피는 방광 조절력이 약해 하룻밤을 참기 힘들 수 있어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103040203, 1030402, '아침에 일어나면 4-1의 아침 루틴부터 다시 반복하기', 3, '이 순서대로 천천히 연습해 주세요. 아침에 일어나면 4-1의 아침 루틴부터 다시 반복해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103040204, 1030402, '1~2주 잘 가려도 끝난 게 아니다 — 짧아야 1개월, 길면 수개월', 4, '1~2주 잘 가려도 끝난 게 아니다 — 짧아야 1개월, 길면 수개월. 오래 걸리는 것은 지능이 아니라 본능이 강한가의 문제예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050101, 1030501, '원인: 푹신한 촉감이 ''패드''로 학습된 것', 1, '카페트나 이불의 푹신한 촉감을 패드처럼 느껴 실수할 수 있어요. 비슷한 촉감의 물건을 잠시 치우고 패드 위치를 분명하게 알려 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050102, 1030501, '패드를 4~5장 겹쳐 카페트보다 두껍고 푹신하게 깐다', 2, '패드를 4~5장 겹쳐 카페트보다 두껍고 푹신하게 깔아요. 이 기간 카페트·발판은 치워요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050103, 1030501, '싸면 맨 위의 싼 패드를 맨 밑으로 내리고 새 패드를 위에(항상 5장 유지)', 3, '패드를 다섯 장 정도 겹쳐 깔고, 사용한 패드는 아래로 옮겨 냄새가 남게 해주세요. 새 패드는 위에 올리며 일주일 정도 같은 방식으로 진행해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050104, 1030501, '일주일 뒤 카페트를 다시 깔고, ''패드=배변 장소'' 지정 훈련과 병행하기', 4, '일주일 뒤 카페트를 다시 깔고, ''패드=배변 장소'' 지정 훈련과 병행해요. ⚠ 실수 장소에서 엎드려 시키고 칭찬하면 ''엎드린 곳=배변 장소''로 묶여요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050105, 1030501, '가장자리에 걸쳐 싸거나 빙빙 돌다 밖에 싸는 개는 ''턱''을 만들기', 5, '패드 가장자리에 걸쳐 배변한다면 방수 방석이나 낮은 박스로 테두리를 만들어 주세요. 강아지가 패드 범위를 쉽게 구분하도록 돕는 방법이에요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050106, 1030501, '혼내면 패드 자체를 거부할 수 있다 — 환경 변화로 교정하기', 6, '아래 상태가 되면 이번 단계를 잘 마친 거예요. 혼내면 패드 자체를 거부할 수 있다 — 환경 변화로 교정해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050201, 1030502, '그게 정상임을 받아들인다', 1, '이번 단계에서 배울 내용을 알려드릴게요. 그게 정상임을 받아들인다 — 싸고 싶은 자리가 확고한 개에게 패드를 강요하지 않아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050202, 1030502, '하루 4번 산책으로 밖에서 싸게 하기', 2, '하루 4번 산책으로 밖에서 싸게 해요. 하루 2번으로는 부족하다 — 안 그러면 ''패드 모서리 폭격기''가 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050203, 1030502, '실내 패드는 절충으로만 유지한다("우리 절충하자")', 3, '실내 패드는 절충으로만 유지한다("우리 절충하자") — 패드를 하나 더 깔아 주는 정도. 그래도 옆에 쌀 수 있어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050204, 1030502, '시간이 지날수록 본능적으로 집에서는 안 하게 되기', 4, '아래 상태가 되면 이번 단계를 잘 마친 거예요. 시간이 지날수록 본능적으로 집에서는 안 하게 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050301, 1030503, '혼내기를 즉시 멈춘다 — 제재할수록 개 입장에선 더 화가 난다', 1, '이 순서대로 천천히 연습해 주세요. 혼내기를 즉시 멈춘다 — 제재할수록 개 입장에선 더 화가 나요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050302, 1030503, '원인을 구분한다: ①안정감 부족(이사 직후 등', 2, '마킹의 원인이 낯선 환경 때문인지, 보호자와의 갈등이나 불안 때문인지 먼저 살펴봐 주세요. 원인을 알아야 강아지에게 맞는 도움을 줄 수 있어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050303, 1030503, '대응은 제재가 아니라 관심·놀이다', 3, '이 순서대로 천천히 연습해 주세요. 대응은 제재가 아니라 관심·놀이다 — 도움 요청이라 생각하고 관찰 시간을 가져요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050304, 1030503, '산책으로 해결하려 하지 않기', 4, '마킹을 산책만으로 해결하려고 하지 마세요. 산책에서는 함께 뛰고 놀며 에너지를 건강하게 사용하는 데 집중해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050401, 1030504, '아기 때는 장난으로 먹기도 하며 흘러가는 행동이다 — 걱정하지 않아도 되기', 1, '이번 단계에서 배울 내용을 알려드릴게요. 아기 때는 장난으로 먹기도 하며 흘러가는 행동이다 — 걱정하지 않아도 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050402, 1030504, '방법은 하나: 야외 배변으로 바꾼다', 2, '방법은 하나: 야외 배변으로 바꿔요. 하루에 한 번만이라도 밖에서 응가를 하게 하고 "우리 이제 만나지 말자" 하며 똥을 보내 줘요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050403, 1030504, '소변만 봐도 좋으니 데리고 나간다', 3, '이 순서대로 천천히 연습해 주세요. 소변만 봐도 좋으니 데리고 나간다 — 어떤 훈련도 하지 않고 자연스럽게 없어져요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(103050404, 1030504, '2주만 해도 줄거나 없어진다', 4, '2주만 해도 줄거나 없어져요. 생후 4개월쯤 되면 집에서 거의 안 쌀 가능성이 커요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104010101, 1040101, '아기 때 깨무는 것은 나쁜 버릇도, 고쳐야 하는 것도 아니다', 1, '아기 때 깨무는 것은 나쁜 버릇도, 고쳐야 하는 것도 아니다 — 그냥 넘어가야 하고 버릇으로 남지 않아요. 이때 훈육으로 접근하면 관계가 망가지고 예민한 성견이 될 수 있어요. 단, 사람 손을 무는 것으로 이 시기를 지나가게 하는 건 더 안 좋아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104010102, 1040101, '무는 이유는 대부분 ''너무 좋아서, 관심이 많아서, 친근감의 표현''이다', 2, '무는 이유는 대부분 ''너무 좋아서, 관심이 많아서, 친근감의 표현이에요. 악의가 있어서 무는 경우는 거의 없어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104010103, 1040101, '무는 욕구는 없앨 수 없다', 3, '무는 욕구는 없앨 수 없다 — 연기처럼 뻗쳐 나가니 환풍기로 잘 빠져나가게 도와줘야 해요. 쫓아다니며 무는 욕구는 가만히 있는 장난감으로 못 풀어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104010104, 1040101, '"하지 마" 리액션이 오히려 무는 것을 강화하기', 4, '"하지 마" 리액션이 오히려 무는 것을 강화해요. 발을 물었을 때의 소리·움직임은 강아지에게 놀이 시작 신호(터그)예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104010105, 1040101, '이갈이는 약 5개월에 시작해 7개월쯤 끝난다', 5, '이갈이는 약 5개월에 시작해 7개월쯤 끝나요. 잔깨물기는 이갈이가 끝나면 대부분 사라진다 — 희망을 갖고 임해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020101, 1040201, '패드·벽지 찢기는 나쁜 뜻이 아니라 노는 행동이다', 1, '패드·벽지 찢기는 나쁜 뜻이 아니라 노는 행동이에요. ''물어도 되는 것''을 만들어 줘요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020102, 1040201, '물고 다닐 수 있고 찢을 수 있는 장난감 몇 개를 따로 마련하기', 2, '물고 다닐 수 있고 찢을 수 있는 장난감 몇 개를 따로 마련해요. 그 장난감으로 놀면 개입하지 않고 차분히 지켜봐요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020103, 1040201, '패드를 찢을 때 "하지 마, 왜 그래" 하며 치워 주는 반응을 주지 않기', 3, '이 순서대로 천천히 연습해 주세요. 패드를 찢을 때 "하지 마, 왜 그래" 하며 치워 주는 반응을 주지 않는다 — 그 반응 자체가 재밌어지는 강아지가 있어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020104, 1040201, '조각을 삼키는 모습이 보이면 즉시 크기·재질을 바꾼다', 4, '장난감 조각을 삼키려고 하면 즉시 크기나 재질을 바꿔 주세요. 삼킬 수 있는 작은 조각이 생기는 장난감은 사용하지 마세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020105, 1040201, '허용된 장난감으로 찢기 욕구를 푸는 모습이 보이면 성공', 5, '강아지가 허용된 장난감으로 찢고 무는 욕구를 풀 수 있으면 잘하고 있는 거예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020201, 1040202, '발과 머리를 쓰는 놀이로 무는 욕구를 푼다', 1, '발과 머리를 함께 쓰는 놀이로 무는 욕구를 건강하게 풀어 주세요. 안 신는 신발이나 종이컵 안에 간식을 숨겨 시작해 보세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020202, 1040202, '신발에 간식을 넣어 뜯어 꺼내 먹게 하기', 2, '이 순서대로 천천히 연습해 주세요. 신발에 간식을 넣어 뜯어 꺼내 먹게 한다 / 옷을 돌돌 말아 간식을 넣는다 / 더 어렵게는 종이컵에 간식을 넣고 싸요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020203, 1040202, '처음엔 살짝만 접어 난이도를 낮춘다', 3, '처음에는 간식을 쉽게 꺼낼 수 있도록 물건을 살짝만 접어 주세요. 강아지가 보호자에게 도움을 요청하면 조금 도와 성공 경험을 만들어 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020204, 1040202, '규칙: 보호자 손에 간식을 들고 있으면 안 되기', 4, '규칙: 보호자 손에 간식을 들고 있으면 안 된다 — 간식은 물건 안에만, 강아지가 스스로 풀어요. 다음 판은 천천히 냄새 맡게 하며 다시 줘요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020205, 1040202, '기간: 생후 1개월부터 시작 가능', 5, '기간: 생후 1개월부터 시작 가능. 이갈이 끝나고 두 달, 약 10개월~1년까지 매일 해 줘요. 짜증내며 손을 물면 머리 쓰기가 안 돼서다 — 쉽게 만들어 다시 줘요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020206, 1040202, '나중엔 신발을 물어뜯으라 해도 안 뜯고', 6, '아래 상태가 되면 이번 단계를 잘 마친 거예요. 나중엔 신발을 물어뜯으라 해도 안 뜯고, 손을 입에 넣어도 안 무는 시기가 와요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020301, 1040203, '손과 ''물 것''의 역할을 가른다', 1, '손과 ''물 것''의 역할을 결정해요. 📖 식욕이 좋으면 훈련은 절반이 끝났다고 봐도 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020302, 1040203, '기준은 하나: 내가 준 물건을 물면 그대로 둔다', 2, '이 순서대로 천천히 연습해 주세요. 기준은 하나: 내가 준 물건을 물면 그대로 둔다 / 주지 않은 물건을 물면 ''이놈!'' 하고 짧게 놀라게 해 멈춘다 / 손을 물면 허용된 다른 물건으로 시선을 돌려요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020303, 1040203, '손을 깨물며 노는 기억을 많이 남기지 말고 다른 것들을 많이 물게 하기', 3, '손을 깨물며 노는 기억을 많이 남기지 말고 다른 것들을 많이 물게 해요. 손은 ''나를 예뻐해주는 손''으로만 배우게 해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104020304, 1040203, '잔깨물기는 이갈이가 끝나면 대부분 자연스럽게 없어진다', 4, '아래 상태가 되면 이번 단계를 잘 마친 거예요. 잔깨물기는 이갈이가 끝나면 대부분 자연스럽게 없어져요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030101, 1040301, '장난감을 던져만 주고 알아서 놀게 하는 방식은 안 되기', 1, '이번 단계에서 배울 내용을 알려드릴게요. 장난감을 던져만 주고 알아서 놀게 하는 방식은 안 된다 — "이거 어떻게 놀라고"가 돼요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030102, 1040301, '보호자가 같이 뛰고, 같이 놀고, 같이 쉬어 주기', 2, '보호자가 같이 뛰고, 같이 놀고, 같이 쉬어 줘요. 그러면 혼낼 자격이 생겨요. 어릴 때는 물어 봐야 한다 — 뭐가 안 되는지도 알아야 해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030103, 1040301, '노는 게 아니라 멈추는 걸 배운다', 3, '노는 중에 물면 받아 주고, 강아지가 잠깐 멈추는 순간 "옳지" 하며 놀아 준다 — 노는 게 아니라 멈추는 걸 배워요. 흥분 자체를 막지 않아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030104, 1040301, '이갈이가 끝나면 "집에서는 안 돼, 밖에서만 하자"로 장소를 옮긴다', 4, '아래 상태가 되면 이번 단계를 잘 마친 거예요. 이갈이가 끝나면 "집에서는 안 돼, 밖에서만 하자"로 장소를 옮겨요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030201, 1040302, '무는 욕구를 빼 주는 환풍기', 1, '함께 당기고 놓아주는 놀이로 무는 욕구를 충분히 풀어 주세요. 강아지가 안전하게 물 수 있는 튼튼한 장난감을 준비해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030202, 1040302, '다시 물게 하기를 반복하기', 2, '이 순서대로 천천히 연습해 주세요. 장난감으로 계속 놀아주며 물게 하고, 뺏어 주고, 다시 물게 하기를 반복해요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030203, 1040302, '놀이 중 턱을 만져 주면 더 좋아하기', 3, '놀이 중 턱을 만져 주면 더 좋아한다 → 주둥이도 잡아 주고 귀도 간지럽혀요. 더 세게 무는 게 정상 반응. 자고 있을 때도 장난감을 물고 있게 해 줘요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030204, 1040302, '기간: 최소 1년, "언제까지가 없다"', 4, '기간: 최소 1년, "언제까지가 없다". 많이 해서 손해 보는 건 없어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030205, 1040302, '계속 해줄수록 손 깨물기·이갈이·여기저기 무는 것이 줄어든다', 5, '아래 상태가 되면 이번 단계를 잘 마친 거예요. 계속 해줄수록 손 깨물기·이갈이·여기저기 무는 것이 줄어들어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030301, 1040303, '손·발을 쫓아다니며 무는 욕구는 ''쫓아가서 무는 놀이''로만 풀린다', 1, '손이나 발을 쫓아 무는 강아지에게는 움직이는 장난감을 쫓는 놀이를 제공해 주세요. 양말이나 행주처럼 한 번 사용하고 버릴 수 있는 장난감이 좋아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030302, 1040303, '양말·행주를 낚시처럼 움직여 쫓아가 물게 하기', 2, '양말·행주를 낚시처럼 움직여 쫓아가 물게 해요. 튼튼한 시판 장난감보다 한 번 갖고 놀고 버릴 것이 좋아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030303, 1040303, '손·발을 깨물지 않게 하고 싶다면 무조건 해야 하는 놀이', 3, '이 순서대로 천천히 연습해 주세요. 손·발을 깨물지 않게 하고 싶다면 무조건 해야 하는 놀이 — 충분히 발산시켜요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030304, 1040303, '충분히 놀아준 뒤 발 물기 제지하기', 4, '충분히 놀아 무는 욕구를 풀어준 다음에 발을 무는 행동을 제지해 주세요. 놀이보다 제지를 먼저 하면 욕구가 남아 교육이 어려워질 수 있어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030401, 1040304, '''보호자와 같은 방향을 본다''는 신뢰를 만들기', 1, '보호자와 같은 방향을 바라보며 함께 움직이는 놀이로 신뢰를 만들어 주세요. 장난감 두 개를 준비하면 흐름을 끊지 않고 이어갈 수 있어요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030402, 1040304, '강아지가 장난감을 물면 무는 방향으로 ''딸려 가 주듯'' 뒤로 당겨 주기', 2, '이 순서대로 천천히 연습해 주세요. 강아지가 장난감을 물면 무는 방향으로 ''딸려 가 주듯'' 뒤로 당겨 줘요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030403, 1040304, '장난감을 가지고 가 버리면 뺏어오지 않기', 3, '이 순서대로 천천히 연습해 주세요. 장난감을 가지고 가 버리면 뺏어오지 않는다 — 다른 장난감을 보여주며 장난치고, 그 사이 원래 장난감은 살짝 숨겨요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030404, 1040304, '물고 있는 동안 얼굴·몸을 만져 주고, 가끔 살짝 밀쳐 방해도 하기', 4, '강아지가 장난감을 무는 동안 얼굴과 몸을 부드럽게 만져 주세요. 가끔 살짝 밀어도 놀이를 이어가면 칭찬해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104030405, 1040304, '장난감 놀이로 ''보호자와 같이 무언가를 한다''를 배우면 성공', 5, '장난감 놀이를 통해 보호자와 함께 활동하는 즐거움을 알게 되면 잘하고 있는 거예요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104040101, 1040401, '목표는 소리에 ''멈칫''하는 것까지만', 1, '이번 단계의 목표는 짧은 소리에 잠깐 멈추는 것이에요. 엎드리거나 반성하는 모습까지 요구하지 말고, 씹을 장난감과 간식을 준비해 주세요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104040102, 1040401, '소리는 "압" 또는 "악" — 짧고 딱 떨어지게', 2, '소리는 "압" 또는 "악" — 짧고 딱 떨어지게. "아이야~"처럼 늘이지 않아요.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
	(104040103, 1040401, '혼내듯이 아니라 노는 것처럼 밝게', 3, '혼내듯이 아니라 노는 것처럼 밝게: 간식을 손에 쥔다 → 물면 "압" → 간식을 줘요. 반복.
